    public static int[] sieve(int n) {
        int[] a = new int[n + 1];
        Arrays.fill(a, 2, n + 1, 1);
        for (int i = 2; i * i <= n; i++) {
            if (a[i] == 1) {
                for (int j = i * i; j <= n; j += i) {
